CREATE OR REPLACE FUNCTION calculate_cpi(
    hist_sign_rating SMALLINT,
    research_val_rating INTEGER,
    cult_score SMALLINT,
    conserve_status TEXT
)
RETURNS FLOAT AS $ $
DECLARE
    conserve_status_map RECORD;
BEGIN
    -- Map ConserveStatus to numerical values
    CASE conserve_status
        WHEN 'Excellent' THEN conserve_status_map := 1;
        WHEN 'Good' THEN conserve_status_map := 3;
        WHEN 'Fair' THEN conserve_status_map := 5;
        WHEN 'Poor' THEN conserve_status_map := 7;
        WHEN 'Critical' THEN conserve_status_map := 10;
    END CASE;

    -- Calculate CPI using the provided formula
    RETURN ((hist_sign_rating + research_val_rating + cult_score) * (10 - conserve_status_map)) / 30.0;
END;
$ $ LANGUAGE plpgsql;

